python3 -c "
import fitz, glob, os, zipfile, xml.etree.ElementTree as ET

base = '/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind/project'
for root, dirs, files in sorted(os.walk(base)):
    for f in sorted(files):
        p = os.path.join(root, f)
        rel = os.path.relpath(p, base)
        if f.endswith('.pdf'):
            doc = fitz.open(p)
            print(f'================ {rel} ({len(doc)} pages) ================')
            for i, page in enumerate(doc):
                print(f'--- Page {i+1} ---')
                print(page.get_text())
        elif f.endswith('.docx'):
            print(f'================ {rel} ================')
            with zipfile.ZipFile(p) as z:
                xml_content = z.read('word/document.xml')
            tree = ET.fromstring(xml_content)
            for para in tree.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
                texts = [t.text for t in para.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t') if t.text]
                if texts:
                    print(''.join(texts))
"

python3 -c "
import openpyxl, glob, os

base = '/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind'
for root, dirs, files in sorted(os.walk(base)):
    for f in sorted(files):
        if f.endswith('.xlsx'):
            p = os.path.join(root, f)
            rel = os.path.relpath(p, base)
            wb = openpyxl.load_workbook(p, data_only=False)
            print(f'================ {rel} ================')
            for name in wb.sheetnames:
                ws = wb[name]
                print(f'--- Sheet: {name} (rows: {ws.max_row}, cols: {ws.max_column}) ---')
                for r in range(1, min(ws.max_row+1, 100)):
                    row_vals = [ws.cell(r, c).value for c in range(1, ws.max_column+1)]
                    if any(v is not None for v in row_vals):
                        print(f'Row {r:2d}: {row_vals}')
"

